samples.ButtonProgress:
Column {
    spacing: 12

    EButton {
        id: taskButton

        progress: -1
        text: qsTr("Start task")
        styleType: EStyle.Primary
        enabled: !progressTimer.running

        onClicked: {
            progress = 0
            progressTimer.start()
        }
    }
    Timer {
        id: progressTimer

        repeat: true
        interval: 120

        onTriggered: {
            taskButton.progress = Math.min(1, taskButton.progress + 0.1)
            if (taskButton.progress >= 1)
                stop()
        }
    }
}

