            verticalAlignment: Text.AlignVCenter
            text: table.currentRow ? qsTr("Selected: %1").arg(table.currentRow.name) : qsTr("No selection")
        }
        ETag {
            effect: "plain"
            size: EStyle.Small
            styleType: EStyle.Info
